import React from 'react'
import {DashboardBackground, BodyContainer, InlineContainer, InlineTittle} from './styles';

import Header from '../../components/Header';
import Card from '../../components/Card';

const Dashboard = ()=>{

    
    return(
       <DashboardBackground>
           <Header />
           <BodyContainer>
           <InlineTittle>
                       <h2>Register</h2>
                   </InlineTittle>
               
                   <Card width='2px'>
                       <p>+</p>
                   </Card>
               
               
           </BodyContainer>

       </DashboardBackground>
            
        
    )
}

export default Dashboard;
